-- origin=auto row_preserving=True check=rows_equal
CREATE VIEW v_attendance AS SELECT attendance.link_to_event AS link_to_event, attendance.link_to_member AS link_to_member, member.first_name AS first_name, member.last_name AS last_name, member.email AS email, member.position AS position, member.t_shirt_size AS t_shirt_size, member.phone AS phone, member.zip AS zip, member.link_to_major AS link_to_major, event.event_name AS event_name, event.event_date AS event_date, event.type AS type, event.notes AS notes, event.location AS location, event.status AS status, major.major_name AS major_name, major.department AS department, major.college AS college FROM attendance LEFT JOIN member AS member ON attendance.link_to_member = member.member_id LEFT JOIN event AS event ON attendance.link_to_event = event.event_id LEFT JOIN major AS major ON member.link_to_major = major.major_id;

-- origin=auto row_preserving=True check=rows_equal
CREATE VIEW v_budget AS SELECT budget.budget_id AS budget_id, budget.category AS category, budget.spent AS spent, budget.remaining AS remaining, budget.amount AS amount, budget.event_status AS event_status, budget.link_to_event AS link_to_event, event.event_name AS event_name, event.event_date AS event_date, event.type AS type, event.notes AS notes, event.location AS location, event.status AS status FROM budget LEFT JOIN event AS event ON budget.link_to_event = event.event_id;

-- origin=auto row_preserving=True check=rows_equal
CREATE VIEW v_expense AS SELECT expense.expense_id AS expense_id, expense.expense_description AS expense_description, expense.expense_date AS expense_date, expense.cost AS cost, expense.approved AS approved, expense.link_to_member AS link_to_member, expense.link_to_budget AS link_to_budget, member.first_name AS first_name, member.last_name AS last_name, member.email AS email, member.position AS position, member.t_shirt_size AS t_shirt_size, member.phone AS phone, member.zip AS zip, member.link_to_major AS link_to_major, budget.category AS category, budget.spent AS spent, budget.remaining AS remaining, budget.amount AS amount, budget.event_status AS event_status, budget.link_to_event AS link_to_event, major.major_name AS major_name, major.department AS department, major.college AS college FROM expense LEFT JOIN member AS member ON expense.link_to_member = member.member_id LEFT JOIN budget AS budget ON expense.link_to_budget = budget.budget_id LEFT JOIN major AS major ON member.link_to_major = major.major_id;

-- origin=auto row_preserving=True check=rows_equal
CREATE VIEW v_income AS SELECT income.income_id AS income_id, income.date_received AS date_received, income.amount AS amount, income.source AS source, income.notes AS notes, income.link_to_member AS link_to_member, member.first_name AS first_name, member.last_name AS last_name, member.email AS email, member.position AS position, member.t_shirt_size AS t_shirt_size, member.phone AS phone, member.zip AS zip, member.link_to_major AS link_to_major, major.major_name AS major_name, major.department AS department, major.college AS college FROM income LEFT JOIN member AS member ON income.link_to_member = member.member_id LEFT JOIN major AS major ON member.link_to_major = major.major_id;

-- origin=auto row_preserving=True check=rows_equal
CREATE VIEW v_member AS SELECT member.member_id AS member_id, member.first_name AS first_name, member.last_name AS last_name, member.email AS email, member.position AS position, member.t_shirt_size AS t_shirt_size, member.phone AS phone, member.zip AS zip, member.link_to_major AS link_to_major, zip.type AS type, zip.city AS city, zip.county AS county, zip.state AS state, zip.short_state AS short_state, major.major_name AS major_name, major.department AS department, major.college AS college FROM member LEFT JOIN zip_code AS zip ON member.zip = zip.zip_code LEFT JOIN major AS major ON member.link_to_major = major.major_id;
